# === task_a.py ===
from datetime import date
from decimal import Decimal, InvalidOperation, localcontext

_PUNCTUATION = {".", ",", ";", ":", "'", '"', "(", ")", "/", "-"}
_SUFFIXES = {"SA", "SL", "SLU", "LTD", "LIMITED", "INC", "LLC", "GMBH", "BV", "NV", "SAS"}


def _parse_date(value):
    if not isinstance(value, str):
        raise ValueError("invalid date")
    if len(value) != 10 or value[4] != "-" or value[7] != "-":
        raise ValueError("invalid date format")
    digits = value[0:4] + value[5:7] + value[8:10]
    if not all(ch in "0123456789" for ch in digits):
        raise ValueError("invalid date format")
    try:
        return date(int(value[0:4]), int(value[5:7]), int(value[8:10]))
    except ValueError:
        raise ValueError("invalid calendar date") from None


def _parse_amount(value):
    try:
        amount = Decimal(value)
    except (InvalidOperation, ValueError):
        raise ValueError("invalid amount") from None
    if not amount.is_finite():
        raise ValueError("invalid amount")
    if amount.as_tuple().exponent < -2:
        raise ValueError("invalid amount")
    return amount


def _normalize_vendor(value):
    upper = value.upper()
    removed = "".join(ch for ch in upper if ch not in _PUNCTUATION)
    collapsed = " ".join(removed.split())
    if not collapsed:
        raise ValueError("empty normalized vendor")
    tokens = collapsed.split(" ")
    while tokens and tokens[-1] in _SUFFIXES:
        tokens.pop()
    if not tokens:
        raise ValueError("empty normalized vendor")
    return " ".join(tokens)


def find_duplicate_payments(payments: list[dict], window_days: int = 7) -> list[dict]:
    if isinstance(window_days, bool) or not isinstance(window_days, int):
        raise ValueError("invalid window_days")
    if window_days < 0 or window_days > 365:
        raise ValueError("invalid window_days")
    if not isinstance(payments, list):
        raise ValueError("invalid payments")
    if len(payments) == 0:
        return []
    seen_ids = set()
    parsed = []
    for payment in payments:
        if not isinstance(payment, dict):
            raise ValueError("invalid payment")
        for key in ("id", "date", "vendor", "amount", "currency"):
            if key not in payment:
                raise ValueError("missing payment key")
        payment_id = payment["id"]
        date_value = payment["date"]
        vendor_value = payment["vendor"]
        amount_value = payment["amount"]
        currency_value = payment["currency"]
        if not isinstance(payment_id, str) or not isinstance(date_value, str) or not isinstance(vendor_value, str) or not isinstance(amount_value, str) or not isinstance(currency_value, str):
            raise ValueError("invalid payment field type")
        if payment_id == "":
            raise ValueError("empty payment id")
        if payment_id in seen_ids:
            raise ValueError("duplicate payment id")
        seen_ids.add(payment_id)
        parsed_date = _parse_date(date_value)
        amount = _parse_amount(amount_value)
        vendor = _normalize_vendor(vendor_value)
        currency = currency_value.strip().upper()
        if currency == "":
            raise ValueError("empty currency")
        parsed.append({"id": payment_id, "date_obj": parsed_date, "vendor": vendor, "amount": amount, "currency": currency})
    buckets = {}
    for record in parsed:
        key = (record["vendor"], record["amount"], record["currency"])
        buckets.setdefault(key, []).append(record)
    groups = []
    for (vendor, amount, currency), records in buckets.items():
        sorted_records = sorted(records, key=lambda item: (item["date_obj"], item["id"]))
        current = []
        previous_date = None
        components = []
        for record in sorted_records:
            if current and (record["date_obj"] - previous_date).days > window_days:
                if len(current) >= 2:
                    components.append(current)
                current = []
            current.append(record)
            previous_date = record["date_obj"]
        if len(current) >= 2:
            components.append(current)
        for component in components:
            with localcontext() as ctx:
                ctx.prec = max(50, len(amount.as_tuple().digits) + 5)
                group_amount = amount.quantize(Decimal("0.01"))
            group = {"payment_ids": [item["id"] for item in component], "vendor": vendor, "amount": group_amount, "currency": currency}
            groups.append((component[0]["date_obj"], component[0]["id"], group))
    groups.sort(key=lambda item: (item[0], item[1]))
    return [item[2] for item in groups]

