from calendar import monthrange
from datetime import date


def _parse_date(value):
    if not isinstance(value, str):
        raise ValueError("invalid date")
    if len(value) != 10 or value[4] != "-" or value[7] != "-":
        raise ValueError("invalid date format")
    digits = value[0:4] + value[5:7] + value[8:10]
    if not all(ch in "0123456789" for ch in digits):
        raise ValueError("invalid date format")
    try:
        return date(int(value[0:4]), int(value[5:7]), int(value[8:10]))
    except ValueError:
        raise ValueError("invalid calendar date") from None


def add_months(date_str: str, months: int) -> str:
    if isinstance(months, bool) or not isinstance(months, int):
        raise ValueError("invalid months")
    if months < -2400 or months > 2400:
        raise ValueError("invalid months")
    start_date = _parse_date(date_str)
    total = start_date.year * 12 + (start_date.month - 1) + months
    target_year, month_index = divmod(total, 12)
    target_month = month_index + 1
    if target_year < 1 or target_year > 9999:
        raise ValueError("resulting year out of range")
    start_last = monthrange(start_date.year, start_date.month)[1]
    target_last = monthrange(target_year, target_month)[1]
    if start_date.day == start_last or start_date.day > target_last:
        result_day = target_last
    else:
        result_day = start_date.day
    return f"{target_year:04d}-{target_month:02d}-{result_day:02d}"


def monthly_schedule(start: str, count: int) -> list[str]:
    if isinstance(count, bool) or not isinstance(count, int):
        raise ValueError("invalid count")
    if count < 1 or count > 120:
        raise ValueError("invalid count")
    _parse_date(start)
    return [add_months(start, i) for i in range(1, count + 1)]

