from decimal import Decimal, InvalidOperation, ROUND_HALF_UP, localcontext

_ZERO_MINOR = {"JPY", "KRW"}
_TEN_PLACES = Decimal("0.0000000001")


def _normalize_currency(code):
    if not isinstance(code, str):
        raise ValueError("invalid currency code")
    if len(code) != 3:
        raise ValueError("invalid currency code")
    if not all(("A" <= ch <= "Z" or "a" <= ch <= "z") for ch in code):
        raise ValueError("invalid currency code")
    return code.upper()


def _parse_amount(value):
    if not isinstance(value, str):
        raise ValueError("invalid amount")
    try:
        amount = Decimal(value)
    except (InvalidOperation, ValueError):
        raise ValueError("invalid amount") from None
    if not amount.is_finite():
        raise ValueError("invalid amount")
    return amount


def _validate_rates(rates):
    if not isinstance(rates, dict):
        raise ValueError("invalid rates")
    normalized = {}
    for key, value in rates.items():
        code = _normalize_currency(key)
        if isinstance(value, bool) or not isinstance(value, (str, int, Decimal)):
            raise ValueError("invalid rate")
        try:
            rate = value if isinstance(value, Decimal) else Decimal(str(value))
        except (InvalidOperation, ValueError):
            raise ValueError("invalid rate") from None
        if not rate.is_finite() or rate <= 0:
            raise ValueError("invalid rate")
        normalized[code] = rate
    if "EUR" in normalized:
        if normalized["EUR"] != Decimal(1):
            raise ValueError("invalid EUR rate")
    else:
        normalized["EUR"] = Decimal(1)
    return normalized


def _quantum(currency):
    return Decimal("1") if currency in _ZERO_MINOR else Decimal("0.01")


def convert_fx(amount: str, from_currency: str, to_currency: str, rates: dict) -> Decimal:
    from_code = _normalize_currency(from_currency)
    to_code = _normalize_currency(to_currency)
    amount_value = _parse_amount(amount)
    if from_code == to_code:
        with localcontext() as ctx:
            ctx.prec = 50
            return amount_value.quantize(_quantum(to_code), rounding=ROUND_HALF_UP)
    normalized = _validate_rates(rates)
    if from_code not in normalized or to_code not in normalized:
        raise ValueError("unknown currency")
    with localcontext() as ctx:
        ctx.prec = 50
        eur_amount = amount_value / normalized[from_code]
        result = eur_amount * normalized[to_code]
        return result.quantize(_quantum(to_code), rounding=ROUND_HALF_UP)


def cross_rate(from_currency: str, to_currency: str, rates: dict) -> Decimal:
    from_code = _normalize_currency(from_currency)
    to_code = _normalize_currency(to_currency)
    normalized = _validate_rates(rates)
    if from_code not in normalized or to_code not in normalized:
        raise ValueError("unknown currency")
    with localcontext() as ctx:
        ctx.prec = 50
        result = normalized[to_code] / normalized[from_code]
        return result.quantize(_TEN_PLACES, rounding=ROUND_HALF_UP)
